        shape = frozenset(key)
        color = max(counts, key=lambda x: (counts[x], x))
        variants = orientations(shape)
        for variant in variants:
            mh = max(r for r, c in variant) + 1
            mw = max(c for r, c in variant) + 1
            for r in range(ph - mh + 1):
                for c in range(pw - mw + 1):
                    cells = {(r + dr, c + dc) for dr, dc in variant}
                    if all(panel[y][x] == 1 for y, x in cells):
                        placements.append((len(cells), color, cells))

