def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the rectangular template: its border is one color, and its
    # interior uses only that color plus one pattern color.
    best = None
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    border = grid[r0][c0]
                    if any(grid[r0][c] != border or grid[r1][c] != border
                           for c in range(c0, c1 + 1)):
                        continue
                    if any(grid[r][c0] != border or grid[r][c1] != border
                           for r in range(r0, r1 + 1)):
                        continue
                    pattern_colors = set()
                    valid = True
                    for r in range(r0 + 1, r1):
                        for c in range(c0 + 1, c1):
                            v = grid[r][c]
                            if v != border:
                                pattern_colors.add(v)
                                if len(pattern_colors) > 1:
                                    valid = False
                                    break
                        if not valid:
                            break
                    if valid and pattern_colors:
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if best is None or area > best[0]:
                            best = (area, r0, r1, c0, c1, border,
                                    next(iter(pattern_colors)))

    if best is None:
        return [row[:] for row in grid]

    _, r0, r1, c0, c1, bg, fg = best
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    ph, pw = len(out), len(out[0])

    def components(cells):
        todo = set(cells)
        result = []
        while todo:
            start = todo.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for q in ((r - 1, c), (r + 1, c),
                          (r, c - 1), (r, c + 1)):
                    if q in todo:
                        todo.remove(q)
                        comp.add(q)
                        stack.append(q)
            result.append(comp)
        return result

    def orientations(shape):
        result = set()
        for flip in (1, -1):
            for turns in range(4):
                pts = []
                for r, c in shape:
                    x, y = r, c * flip
                    for _ in range(turns):
                        x, y = y, -x
                    pts.append((x, y))
                mr = min(x for x, y in pts)
                mc = min(y for x, y in pts)
                result.add(frozenset((x - mr, y - mc) for x, y in pts))
        return result

    def shape_key(cells):
        mr = min(r for r, c in cells)
        mc = min(c for r, c in cells)
        shape = frozenset((r - mr, c - mc) for r, c in cells)
        return min(tuple(sorted(v)) for v in orientations(shape))

    # Catalog the colored shapes outside the template.
    catalog = {}
    for color in range(10):
        if color in (bg, fg):
            continue
        cells = {
            (r, c)
            for r in range(h) for c in range(w)
            if not (r0 <= r <= r1 and c0 <= c <= c1)
            and grid[r][c] == color
        }
        for comp in components(cells):
            key = shape_key(comp)
            catalog.setdefault(key, {})
            catalog[key][color] = catalog[key].get(color, 0) + 1

    # Replace each template pattern component with the color of its matching
    # shape in the catalog.
    pattern = {
        (r, c) for r in range(ph) for c in range(pw)
        if out[r][c] == fg
    }
    for comp in components(pattern):
        counts = catalog.get(shape_key(comp))
        if counts:
            color = max(counts, key=lambda col: (counts[col], col))
            for r, c in comp:
                out[r][c] = color

    return out
